"""REQ-PERF-001 and REQ-PERF-002 from measured cycle counts (no estimate): the cycles of each operation are read from the logs
of the final regression (engine tests: cycles from the start pulse to the end pulse of the engine, one vector per line) and
converted to time at 100 MHz. REQ-PERF-001: a verification of a digest of at most 64 bytes within 50 ms (5,000,000 cycles).
REQ-PERF-002: at least 100 signatures per second, so at most 1,000,000 cycles per signature (with PARA_MUL_W 64; the multiplier
of this RTL is bit-serial whatever PARA_MUL_W, see section 14.2.2).
Usage: python perf.py [out.md]   (default: verification/docs/PERF.md)"""
import os
import re
import sys

V = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..')).replace(chr(92), '/')
S = V + '/sim/'


def ec_cycles(s, tag='ec_final'):
    """(name, cycles) of the vectors of an EC set: the log has 'VEC i PASS cycles=n', the manifest 'i<TAB>name'."""
    log, man = S + '%s/%s.log' % (tag, s), S + '%s/%s.txt' % (tag, s)
    if not (os.path.exists(log) and os.path.exists(man)):
        return []
    names = dict(l.split('\t', 1) for l in open(man).read().splitlines() if '\t' in l)
    out = []
    for i, st, c in re.findall(r'VEC (\d+) (PASS|FAIL) cycles=(\d+)', open(log, errors='replace').read()):
        if st == 'PASS':
            out.append((names.get(i, i).strip(), int(c)))
    return out


def unit_cycles(d, names_file):
    log, man = S + d + '/run.log', S + d + '/' + names_file
    if not (os.path.exists(log) and os.path.exists(man)):
        return []
    names = dict(l.split('\t', 1) for l in open(man).read().splitlines() if '\t' in l)
    return [(names.get(i, i).strip(), int(c)) for i, st, c in re.findall(r'VEC (\d+) (PASS|FAIL) cycles=(\d+)', open(log, errors='replace').read())
            if st == 'PASS']


def pick(rows, key):
    for n, c in rows:
        if key in n:
            return n, c
    return None


def main(out):
    lines = ['# Performance measured in simulation', '',
             'Generated by `verification/env/misc/perf.py` from the logs of the final regression. Cycles are the engine '
             'cycles of one operation (tb_ec: from the start pulse to the end pulse; tb_lat and tb_hbs: the same). Time at '
             '100 MHz. Limits: REQ-PERF-001 verification <= 5,000,000 cycles; REQ-PERF-002 signature <= 1,000,000 cycles.', '',
             '| Algorithm | Operation | Vector | Cycles | ms at 100 MHz | Limit | Verdict |', '|---|---|---|---|---|---|---|']
    nfail = 0
    sets = [('Ed25519', 'ed25519', 'rfc0 verify ok', 'rfc0 sign'), ('Ed448', 'ed448', 'rfc0 verify ok', 'rfc0 sign'),
            ('P-256', 'p256', 'hash0 sample verify ok', 'hash0 sample sign'), ('P-384', 'p384', 'sample verify ok', 'sample sign'),
            ('P-521', 'p521', 'sample verify ok', 'sample sign'), ('secp256k1', 'k256', 'rnd0 verify ok', 'rnd0 sign')]
    for alg, s, kv, ks in sets:
        rows = ec_cycles(s)
        for op, key, lim in (('verify', kv, 5000000), ('sign', ks, 1000000)):
            r = pick([x for x in rows if not x[0].endswith('vas')], key)
            if r is None:
                lines.append('| %s | %s | - | no log | - | %d | not measured |' % (alg, op, lim))
                continue
            ok = r[1] <= lim
            nfail += not ok
            lines.append('| %s | %s | %s | %d | %.1f | %d | %s |' % (alg, op, r[0], r[1], r[1] / 1e5, lim, 'meets' if ok else 'FAILS'))
    for d, names in (('lat_all', 'lat_names.txt'), ('hbs_slh', 'hbs_names.txt')):
        for n, c in unit_cycles(d, names):
            is_sign = re.search(r"\bsign\b", n) is not None
            is_vrfy = (('verify valid' in n) or (n.endswith(' valid') or n.endswith('valid with context'))) and not is_sign
            if is_sign or is_vrfy:
                # DEC-048: the 100 signatures per second of REQ-PERF-002 apply to the elliptic-curve algorithms only
                lim = (None if n.startswith('ML-DSA') or n.startswith('HashML') else 1000000) if is_sign else 5000000
                if lim is None:
                    lines.append('| %s | sign | %s | %d | %.1f | reported (DEC-048) | %.0f signatures/s |' % (n.split()[0], n, c, c / 1e5, 1e8 / c))
                    continue
                ok = c <= lim
                nfail += not ok
                lines.append('| %s | %s | %s | %d | %.1f | %d | %s |' % (n.split()[0], 'sign' if is_sign else 'verify', n, c, c / 1e5,
                                                                      lim, 'meets' if ok else 'FAILS'))
    lines += ['', '%d operations fail their limit.' % nfail if nfail else 'Every measured operation meets its limit.']
    open(out, 'w', encoding='utf-8').write('\n'.join(lines) + '\n')
    print('%s written, %d failing operations' % (out, nfail))


if __name__ == '__main__':
    main(sys.argv[1] if len(sys.argv) > 1 else V + '/docs/PERF.md')
